def count_passed(scores, line):
    count = 0
    for s in scores:
        if s >= line:
            count += 1
    return count

print(count_passed([45, 80, 62, 90, 30], 60))

def evens(n):
    result = []
    for i in range(1, n + 1):
        if i % 2 == 0:
            result.append(i)
    return result

print(evens(10))
